DASHBOARD_HTML = """<!doctype html><html><head><meta charset=utf-8><meta name=viewport content='width=device-width,initial-scale=1'><title>PlantGuard</title><style>body{font-family:sans-serif;max-width:720px;margin:auto;padding:18px;background:#f4f7f3}section{background:white;padding:14px;margin:10px 0;border-radius:10px}dt{font-weight:bold}dd{margin:0 0 8px}.bad{color:#a22}</style></head><body><h1>PlantGuard</h1><section><h2>传感器</h2><dl id=s></dl></section><section><h2>相机与计算</h2><dl id=c></dl></section><section><h2>设备状态</h2><div id=e>加载中</div></section><script>const names={temperature_c:'温度 °C',air_humidity_pct:'空气湿度 %',lux:'照度 lux',full_spectrum:'全光谱',infrared:'红外',visible:'可见光'};function rows(o,m){return Object.keys(m).map(k=>`<dt>${m[k]}</dt><dd>${o&&o[k]!=null?o[k]:'--'}</dd>`).join('')}async function go(){try{let r=await fetch('/api/v1/state');let x=await r.json();s.innerHTML=rows(x.sensor,names);let a=x.camera||{};c.innerHTML=`<dt>蓝色指标</dt><dd>${a.blue_value??'--'}</dd><dt>最终结果</dt><dd>${x.calculation.value??'未配置'} (${x.calculation.status})</dd>`;e.textContent=`C3: ${x.sensor?'online':'waiting'} / CAM: ${x.camera?'reported':'waiting'} / 传感器年龄: ${x.sensor_age_ms??'--'} ms`}catch(q){e.textContent='服务暂不可用';e.className='bad'}}go();setInterval(go,5000)</script></body></html>"""

